function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw cut
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2);
  ctx.lineTo(W/2 + 50, H/2);
  ctx.stroke();

  // show seeds
  ctx.fillStyle = 'black';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + Math.cos(t + i) * 20, H/2 + Math.sin(t + i) * 20, 5, 0, 2 * Math.PI);
    ctx.fill();
  }

  // show cut effect
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 40, 0, Math.PI);
  ctx.fill();

  ctx.restore();
}
